from dataclasses import dataclass


@dataclass
class Batch:
    code: str
    received: str
    expires: str


def fifo(batches):
    return min(batches,
               key=lambda b: b.received)


def fefo(batches):
    return min(batches,
               key=lambda b: b.expires)


class Store:
    def __init__(self, batches, pick=fifo):
        self.batches = batches
        self.pick = pick

    def issue(self):
        batch = self.pick(self.batches)
        self.batches.remove(batch)
        return batch.code


stock = [Batch("A", "2026-01", "2027-06"),
         Batch("B", "2026-03", "2026-12")]
print(Store(list(stock)).issue())
print(Store(list(stock), fefo).issue())

