class Issue:
    def __init__(self, stock, name, n):
        self.stock = stock
        self.name = name
        self.n = n

    def do(self):
        self.stock[self.name] -= self.n

    def undo(self):
        self.stock[self.name] += self.n


class History:
    def __init__(self):
        self._done = []

    def run(self, command):
        command.do()
        self._done.append(command)

    def undo(self):
        self._done.pop().undo()


stock = {"Шолом": 5}
history = History()
history.run(Issue(stock, "Шолом", 2))
history.run(Issue(stock, "Шолом", 1))
print(stock)
history.undo()
